import { defineEval } from "@grok/agent-sdk/evals";

const WINDOW = "2026-08-26/2026-09-02";

function weekly(): string {
  return [
    `Weekly AGENTS.md review for acme/api (${WINDOW}).`,
    "Read week/ and week/tree/. Call apply_agents once.",
  ].join("\n");
}

const AGENTS = [
  "# API",
  "",
  "Usage events are protobuf messages in `proto/billing.proto`.",
  "Every new billing field goes on `UsageEvent`.",
  "Do not add ad-hoc billing columns on the request path.",
  "",
].join("\n");

const CHORE = [
  "# Merged pull requests",
  "",
  "## #12 Fix sidebar opener lint failure",
  "url: https://github.com/acme/api/pull/12",
  "author: @sam",
  "merged: 2026-08-28T16:00:00Z",
  "files: src/sidebar.ts",
  "",
  "Quote style only.",
  "",
].join("\n");

const RULE = [
  "# Merged pull requests",
  "",
  "## #18 Route every billing write through UsageEvent",
  "url: https://github.com/acme/api/pull/18",
  "author: @sam",
  "merged: 2026-08-29T18:00:00Z",
  "files: proto/billing.proto, src/billing.ts",
  "",
  "Adds usage_unit and workspace_id to UsageEvent.",
  "",
  "### comments",
  "- @lee: always put new billing fields on UsageEvent. no request-path columns.",
  "",
].join("\n");

const SLACK = [
  "## #eng-api",
  "- <@U1>: lunch at 12",
  "- <@U2>: yes, every new billing field goes on UsageEvent from now on",
  "",
].join("\n");

export default defineEval({
  tags: ["smoke"],
  cases: [
    {
      id: "skip-chore",
      description: "A lint-only week does not open an AGENTS.md PR.",
      async test(t) {
        await t.send(weekly(), {
          workspaceFiles: {
            "week/window.txt": `${WINDOW}\n`,
            "week/repo.txt": "acme/api\n",
            "week/base.ref": "main\n",
            "week/files.txt": "AGENTS.md\n",
            "week/prs.md": CHORE,
            "week/slack.md": "## #eng-api\n- <@U1>: lunch at 12\n",
            "week/tree/AGENTS.md.txt": AGENTS,
          },
        });
        t.succeeded();
        t.calledTool("apply_agents", { input: { verdict: "skip" } });
      },
    },
    {
      id: "update-rule",
      description: "A repeated billing rule opens an AGENTS.md update.",
      async test(t) {
        await t.send(weekly(), {
          workspaceFiles: {
            "week/window.txt": `${WINDOW}\n`,
            "week/repo.txt": "acme/api\n",
            "week/base.ref": "main\n",
            "week/files.txt": "AGENTS.md\n",
            "week/prs.md": RULE,
            "week/slack.md": SLACK,
            "week/tree/AGENTS.md.txt": "# API\n\nKeep handlers thin.\n",
          },
        });
        t.succeeded();
        t.calledTool("apply_agents", { input: { verdict: "update" } });
      },
    },
    {
      id: "skip-known",
      description: "A rule already in AGENTS.md stays quiet.",
      async test(t) {
        await t.send(weekly(), {
          workspaceFiles: {
            "week/window.txt": `${WINDOW}\n`,
            "week/repo.txt": "acme/api\n",
            "week/base.ref": "main\n",
            "week/files.txt": "AGENTS.md\n",
            "week/prs.md": RULE,
            "week/slack.md": SLACK,
            "week/tree/AGENTS.md.txt": AGENTS,
          },
        });
        t.succeeded();
        t.calledTool("apply_agents", { input: { verdict: "skip" } });
      },
    },
    {
      id: "skip-empty",
      description: "An empty week does not open an AGENTS.md PR.",
      async test(t) {
        await t.send(weekly(), {
          workspaceFiles: {
            "week/window.txt": `${WINDOW}\n`,
            "week/repo.txt": "acme/api\n",
            "week/base.ref": "main\n",
            "week/files.txt": "\n",
            "week/prs.md": "No merged pull requests this week.\n",
            "week/slack.md": "No Slack channels configured.\n",
          },
        });
        t.succeeded();
        t.calledTool("apply_agents", { input: { verdict: "skip" } });
      },
    },
  ],
});
